<?php if($batch->source_sheet||$batch->parsed_line_total!==NULL):?><div class="card shadow-sm mb-3"><div class="card-header"><h2 class="card-title mb-0">Workbook Normalization</h2></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Selected worksheet</dt><dd class="col-sm-8"><?=html_escape($batch->source_sheet?:'—')?></dd><dt class="col-sm-4">Parsed priced-line total</dt><dd class="col-sm-8"><?=$batch->parsed_line_total!==NULL?number_format($batch->parsed_line_total,2):'—'?></dd><dt class="col-sm-4">Source declared total</dt><dd class="col-sm-8"><?=$batch->source_declared_total!==NULL?number_format($batch->source_declared_total,2):'—'?></dd><dt class="col-sm-4">Variance</dt><dd class="col-sm-8"><?=$batch->total_variance!==NULL?number_format($batch->total_variance,2):'—'?></dd><dt class="col-sm-4">Unpriced lines</dt><dd class="col-sm-8"><?=number_format($batch->unpriced_rows)?></dd></dl><?php $material_variance=$batch->total_variance!==NULL&&abs((float)$batch->total_variance)>max(1.00,((int)$batch->total_rows)*0.01);if($material_variance):?><div class="alert alert-warning mt-3 mb-0">The parsed priced-line total differs from the workbook's declared total by <?=number_format(abs($batch->total_variance),2)?>. Review the source before committing.</div><?php endif;?><?php if($batch->normalization_notes):?><p class="small text-body-secondary mt-3 mb-0"><?=html_escape($batch->normalization_notes)?></p><?php endif;?></div></div><?php endif;?>
<div class="row g-3 mb-3"><div class="col-md-8"><div class="card shadow-sm h-100"><div class="card-body"><dl class="row mb-0"><dt class="col-4">File</dt><dd class="col-8"><?=html_escape($batch->original_file_name)?></dd><dt class="col-4">Status</dt><dd class="col-8"><?=html_escape($batch->import_status)?></dd><dt class="col-4">Rows</dt><dd class="col-8"><?=$batch->total_rows?> total · <?=$batch->valid_rows?> valid · <?=$batch->invalid_rows?> invalid</dd></dl></div></div></div><div class="col-md-4"><div class="card shadow-sm h-100"><div class="card-body"><?php if($can_manage&&$batch->import_status==='READY'):?><?=form_open('boq/'.$boq->boq_id.'/imports/'.$batch->boq_import_batch_id.'/commit')?><button class="btn btn-success w-100">Import Validated Rows</button><?=form_close()?><?php elseif($batch->import_status==='INVALID'):?><div class="alert alert-warning mb-0">Correct the errors and upload a new batch.</div><?php endif;?><a class="btn btn-outline-secondary w-100 mt-2" href="<?=site_url('boq/'.$boq->boq_id)?>">Back to BOQ</a></div></div></div></div>
<div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Validation Report</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Sheet / Row</th><th>Reference</th><th>Description</th><th>UOM</th><th>Quantity</th><th>Rate</th><th>Amount</th><th>Status</th><th>Errors</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=html_escape(($r->source_sheet?:'CSV').' / '.$r->source_row_no)?></td><td><?=html_escape($r->item_reference?:'—')?></td><td><?=html_escape($r->item_description?:'—')?></td><td><?=html_escape($r->source_uom_text?:'—')?></td><td><?=html_escape($r->quantity_text?:'—')?></td><td><?=html_escape($r->unit_rate_text?:'—')?></td><td><?=html_escape($r->line_amount_text?:'—')?></td><td><span class="badge text-bg-<?=$r->validation_status==='VALID'||$r->validation_status==='IMPORTED'?'success':'danger'?>"><?=html_escape($r->validation_status)?></span></td><td><?php foreach((array)json_decode($r->validation_errors?:'[]',TRUE)as$e):?><div><?=html_escape($e)?></div><?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
